function migrateSeedHistory(){
 for(const seed of SEEDED_HISTORY){
  const index=s.history.findIndex(h=>h.seedId===seed.seedId||(h.day===seed.day&&String(h.date||'').slice(0,10)===seed.date.slice(0,10)));
  if(index<0){
   s.history.push(JSON.parse(JSON.stringify(seed)));
  }else{
   // Frühere Versionen speicherten teilweise nur Positionsnummern. Sobald sich
   // die Reihenfolge eines Trainingsplans änderte, wurden Gewichte dadurch dem
   // falschen Gerät zugeordnet (z. B. 32 kg Beinpresse als Brustpresse).
   // Für die bekannten übernommenen Trainings stellen wir deshalb die originale
   // Übungsreihenfolge und die dazugehörigen Satzwerte wieder eindeutig her.
   const existing=s.history[index]||{};
   s.history[index]={...existing,...JSON.parse(JSON.stringify(seed)),notes:existing.notes||seed.notes,cardio:{...seed.cardio,...(existing.cardio||{})}};
  }
 }
 s.history.sort((a,b)=>new Date(b.date)-new Date(a.date));
}
migrateSeedHistory();
const MEASUREMENT_KEYS=['Gewicht','Bauchnabel','Hüfte','Brustwarze','Schenkel','Arm','Arm angespannt'];
function carryForwardMeasurements(){
  const last={};
  s.measurements.sort((a,b)=>a.date.localeCompare(b.date));
  s.measurements.forEach(m=>MEASUREMENT_KEYS.forEach(k=>{
    const v=m[k];
    if(v!==null&&v!==undefined&&v!==''&&Number.isFinite(Number(v))){m[k]=Number(v);last[k]=Number(v)}
    else if(last[k]!==undefined)m[k]=last[k];
  }));
}
