const app=document.getElementById('app');function recalcChakra(){
  s.xp=s.history.reduce((sum,h)=>sum+120+Object.values(h.done||{}).filter(Boolean).length*5,0);
}
function migrateCurrentPlan(){
  if(!s.current||!PLANS[s.current.day]||s.planVersion===APP_VERSION)return;
  const oldExercises=s.current.exercises||[];
  const oldValues=s.current.values||{},oldReps=s.current.reps||{},oldDone=s.current.done||{},oldSkipped=s.current.skipped||{},oldNotes=s.current.exerciseNotes||{};
  const byName={};
  oldExercises.forEach((exercise,i)=>{
    const name=exercise?.name;
    if(!name)return;
    byName[name]={values:{},reps:{},done:{},skipped:!!oldSkipped[i],note:oldNotes[i]||''};
    for(let j=0;j<6;j++){
      const key=i+'-'+j;
      if(oldValues[key]!==undefined)byName[name].values[j]=oldValues[key];
      if(oldReps[key]!==undefined)byName[name].reps[j]=oldReps[key];
      if(oldDone[key]!==undefined)byName[name].done[j]=oldDone[key];
    }
  });
  const exercises=JSON.parse(JSON.stringify(PLANS[s.current.day].exercises));
  const suggested=suggestedForExercises(exercises);
  const values={...suggested.values},reps={...suggested.reps},done={},skipped={},exerciseNotes={};
  exercises.forEach((exercise,i)=>{
    const old=byName[exercise.name];
    if(!old)return;
    for(let j=0;j<6;j++){
      const key=i+'-'+j;
      if(old.values[j]!==undefined)values[key]=old.values[j];
      if(old.reps[j]!==undefined)reps[key]=old.reps[j];
      if(old.done[j]!==undefined)done[key]=old.done[j];
    }
    if(old.skipped)skipped[i]=true;
    if(old.note)exerciseNotes[i]=old.note;
  });
  s.current={...s.current,exercises,values,reps,done,skipped,exerciseNotes};
}
function createLocalBackup(reason='Manuell'){
  const payload={version:APP_VERSION,createdAt:new Date().toISOString(),reason,data:JSON.parse(JSON.stringify(s))};
  localStorage.setItem(BACKUP_KEY,JSON.stringify(payload));
  localStorage.setItem(BACKUP_META_KEY,JSON.stringify({createdAt:payload.createdAt,reason}));
  return payload;
}
function automaticBackup(){
  const meta=JSON.parse(localStorage.getItem(BACKUP_META_KEY)||'null');
  const age=meta?.createdAt?Date.now()-new Date(meta.createdAt).getTime():Infinity;
  if(age>24*60*60*1000)createLocalBackup('Automatische tägliche Sicherung');
}
const installedVersion=localStorage.getItem(VERSION_KEY);
if(installedVersion!==APP_VERSION){
  if(localStorage.getItem(KEY))createLocalBackup(`Sicherung vor Update auf ${APP_VERSION}`);
  localStorage.setItem(VERSION_KEY,APP_VERSION);
}
