function achievementsHtml(){return `<div class="achievement-grid">${achievementData().map(a=>`<div class="achievement ${a.done?'unlocked':''}"><div class="achievement-icon">${a.done?a.icon:'🔒'}</div><b>${a.name}</b><div class="small">${a.desc}${a.done?' · erreicht':''}</div></div>`).join('')}</div>`}
function showRankUp(rank){document.body.insertAdjacentHTML('beforeend',`<div class="rankup-overlay" id="rankupOverlay"><div class="rankup-modal"><div class="small">RANGAUFSTIEG</div><div class="rankup-avatar">${rank.icon}</div><h2>${rank.name}</h2><p>${rank.title}</p><div class="character-quote">${rank.quote}</div><button class="btn primary" id="closeRankup">Weitertrainieren</button></div></div>`);document.getElementById('closeRankup').onclick=()=>document.getElementById('rankupOverlay')?.remove()}

