function home(){const last=s.history[0],wp=weightProgress(),ws=weeklyMissionStats();app.innerHTML=`${brand()}${rankCardHtml()}<div class="weight-progress-card"><div class="weight-progress-top"><div><div class="weight-progress-title">Gewichtspfad</div><div class="small">${wp.lost>=0?wp.lost.toFixed(1)+' kg geschafft':Math.abs(wp.lost).toFixed(1)+' kg über Start'}</div></div><div class="weight-progress-values"><strong>${wp.latest.toFixed(1)} kg</strong><span class="small">noch ${wp.remaining.toFixed(1)} kg</span></div></div><div class="shinobi-track"><div class="shinobi-fill" style="width:${wp.pct}%"></div><div class="shinobi-marker" style="left:${Math.max(2,Math.min(98,wp.pct))}%">忍</div></div><div class="weight-progress-meta"><span>Start ${wp.start.toFixed(1)}</span><span>${wp.pct.toFixed(0)} %</span><span>Ziel ${wp.target.toFixed(1)}</span></div></div><div class="home-quick-grid"><div class="home-quick"><span class="small">🔥 Aktiver Streak</span><strong>${ws.streak} ${ws.streak===1?'Woche':'Wochen'}</strong></div><div class="home-quick"><span class="small">Diese Woche</span><strong>${ws.current}/${ws.target} Missionen</strong></div></div><h2 class="scroll-title">Mission starten</h2>${Object.entries(PLANS).map(([k,p],i)=>{const required=p.exercises.filter(x=>!x.optional).length,optional=p.exercises.filter(x=>x.optional).length;return `<div class="day parchment" data-day="${k}"><div class="top"><div style="display:grid;grid-template-columns:34px minmax(0,1fr);gap:10px;align-items:start;min-width:0"><span class="seal-mark">${['体','力','忍'][i]}</span><div style="min-width:0"><b>Mission ${k}</b><div class="sub" style="margin-top:3px">${p.title}</div></div></div><span class="mission-rank">${['B-Rang','A-Rang','S-Rang'][i]}</span></div><span class="pill">${required} Pflicht${optional?` · ${optional} optional`:''}</span></div>`}).join('')}${last?`<h2>Letzte Mission</h2><div class="card compact-last-mission"><div><b>Mission ${last.day} · ${last.title}</b><div class="meta">${new Date(last.date).toLocaleDateString('de-DE')} · ${missionStats(last).sets} Sätze</div></div><span class="mission-rank">${missionGrade(last)}-Rang</span></div>`:''}`}
function workouts(){app.innerHTML=`${brand()}<h2 class="scroll-title">Deine Missionen</h2>
${Object.entries(PLANS).map(([k,p],i)=>`<div class="day parchment" data-day="${k}"><div class="top"><div style="display:grid;grid-template-columns:34px minmax(0,1fr);gap:10px;align-items:start;min-width:0"><span class="seal-mark">${['体','力','忍'][i]}</span><div style="min-width:0"><b>Mission ${k}</b><div class="sub" style="margin-top:3px">${p.title}</div></div></div><span class="mission-rank">${['B-Rang','A-Rang','S-Rang'][i]}</span></div><span class="pill">Ganzkörper · Cardio · ${p.exercises.filter(x=>!x.optional).length} Pflicht${p.exercises.some(x=>x.optional)?` · ${p.exercises.filter(x=>x.optional).length} optional`:``}</span></div>`).join('')}
<h2>Eigene Missionen</h2>
${s.customMissions.map(m=>`<div class="day parchment"><div class="top"><div><b>${m.title}</b><div class="sub">${m.exercises.length} Übungen</div></div><div class="history-actions"><button class="btn primary" data-day="${m.id}">Starten</button><button class="btn-delete" data-delete-custom="${m.id}">Löschen</button></div></div></div>`).join('')||'<div class="card small">Noch keine eigene Mission gespeichert.</div>'}
<div class="card"><h3>Eigene Mission erstellen</h3><label>Name der Mission</label><input class="field" id="customMissionName" placeholder="z. B. Freies Ganzkörpertraining"><div id="customExerciseRows"><div class="grid2 custom-ex-row"><select class="custom-exercise"><option value="">Übung auswählen …</option>${exerciseOptions()}</select><label class="pill"><input type="checkbox" class="custom-optional"> optional</label></div></div><div class="history-actions" style="margin-top:12px"><button class="btn secondary" id="addCustomExercise">Weitere Übung</button><button class="btn primary" id="saveCustomMission">Mission speichern</button></div></div>`}
function getPlan(k){if(PLANS[k])return PLANS[k];return s.customMissions.find(m=>m.id===k)||null}
function exerciseOptions(selected=''){const groups={'Gerätetraining':EXERCISE_LIBRARY.filter(x=>x.category!=='Freie Übungen'),'Freie Übungen':EXERCISE_LIBRARY.filter(x=>x.category==='Freie Übungen')};return Object.entries(groups).map(([g,items])=>`<optgroup label="${g}">${items.map(x=>`<option value="${x.name}" ${selected===x.name?'selected':''}>${x.name}</option>`).join('')}</optgroup>`).join('')}

function setCount(scheme){const m=String(scheme).match(/^(\d+)/);return m?Number(m[1]):3}
function repTop(scheme){const m=String(scheme).match(/[–-](\d+)/);return m?Number(m[1]):null}
function exerciseNamesForRecord(record){if(Array.isArray(record.exerciseSnapshot)&&record.exerciseSnapshot.length)return record.exerciseSnapshot.map(x=>x.name);if(Array.isArray(record.exercises)&&record.exercises.length)return record.exercises.map(x=>x.name);if(Array.isArray(record.exerciseNames))return record.exerciseNames;return (getPlan(record.day)?.exercises||[]).map(x=>x.name)}
function validCompletedSet(h,q){return !!h.done?.[q]&&Number(h.reps?.[q])>0}
function recordSet(h,i,j){
 const q=i+'-'+j, snap=h.exerciseSnapshot?.[i];
 const live={done:!!h.done?.[q],reps:h.reps?.[q],value:h.values?.[q]};
 const frozen={done:!!snap?.done?.[j],reps:snap?.reps?.[j],value:snap?.values?.[j]};
 // Live- und Snapshot-Daten feldweise zusammenführen. Dadurch kann ein leerer
 // Altwert keinen korrekt gespeicherten Snapshot mehr überschreiben.
 return{
  done:live.done||frozen.done,
  reps:Number(live.reps)>0?live.reps:(Number(frozen.reps)>0?frozen.reps:live.reps??frozen.reps??null),
  value:Number(live.value)>0?live.value:(Number(frozen.value)>0?frozen.value:live.value??frozen.value??null)
 }
}
function recordExercise(h,i){const names=exerciseNamesForRecord(h),name=names[i];return h.exerciseSnapshot?.[i]||h.exercises?.[i]||EXERCISE_LIBRARY.find(x=>x.name===name)||{bodyweight:false}}
// Für Abschluss und Verlauf ist das aktive Abhaken plus eine gültige
// Wiederholungszahl maßgeblich. Das Gewicht wird bereits beim Abhaken validiert,
// darf aber ältere Trainings nicht nachträglich als "nicht absolviert" entwerten.
function validRecordSet(h,i,j){const x=recordSet(h,i,j);return x.done&&Number(x.reps)>0}
function previousExercise(name){for(const h of s.history){const names=exerciseNamesForRecord(h);const i=names.indexOf(name);if(i<0||h.skipped?.[i])continue;const sets=[];for(let j=0;j<6;j++){const q=i+'-'+j;if(validRecordSet(h,i,j)){const rs=recordSet(h,i,j);sets.push({w:rs.value,r:rs.reps,done:true})}}if(sets.length)return{date:h.date,sets}}return null}
function suggestedForExercises(exercises){const values={},reps={};exercises.forEach((x,i)=>{const prev=previousExercise(x.name);if(!prev)return;for(let j=0;j<setCount(x.scheme);j++){const set=prev.sets[j]||prev.sets.at(-1);if(!set)continue;const q=i+'-'+j;values[q]=set.w;reps[q]=set.r}});return{values,reps}}
function ensure(k){
 if(!s.current){const exercises=JSON.parse(JSON.stringify(getPlan(k).exercises));const suggested=suggestedForExercises(exercises);s.current={day:k,date:new Date().toISOString(),startedAt:new Date().toISOString(),exercises,values:suggested.values,reps:suggested.reps,done:{},skipped:{},exerciseNotes:{},cardio:{type:'Laufband',minutes:15,intensity:'mittel',device:'',done:false},strengthMinutes:60,effort:'mittel',notes:''};}
 s.current.exercises=s.current.exercises||JSON.parse(JSON.stringify(getPlan(s.current.day||k).exercises));s.current.exercises.forEach(x=>{const lib=EXERCISE_LIBRARY.find(y=>y.name===x.name);if(lib)x.optional=!!lib.optional});s.current.skipped=s.current.skipped||{};s.current.exerciseNotes=s.current.exerciseNotes||{};s.current.cardio=s.current.cardio||{type:'Laufband',minutes:15,intensity:'mittel',device:'',done:false};save();
}
function exerciseHistory(name){const out=[];for(const h of s.history){const names=exerciseNamesForRecord(h);const i=names.indexOf(name);if(i<0||h.skipped?.[i])continue;const sets=[];for(let j=0;j<6;j++){const q=i+'-'+j;if(validRecordSet(h,i,j)){const rs=recordSet(h,i,j);sets.push({w:rs.value,r:rs.reps,done:true})}}if(sets.length)out.push({date:h.date,sets})}return out}
function targetReached(entry,exercise){if(!entry)return false;const needed=setCount(exercise.scheme),top=repTop(exercise.scheme);const sets=entry.sets.slice(0,needed);if(!top||sets.length<needed)return false;const weights=sets.map(x=>Number(x.w));return sets.every(x=>x.done&&Number(x.r)>=top&&Number.isFinite(Number(x.w))&&Number(x.w)>0)&&weights.every(w=>w===weights[0])}
function progressionState(exercise){const history=exerciseHistory(exercise.name),latest=history[0];if(!targetReached(latest,exercise))return{cls:'progression-hold',text:'🔴 Gewicht beibehalten'};const previous=history[1];const sameWeight=previous&&targetReached(previous,exercise)&&Number(previous.sets[0]?.w)===Number(latest.sets[0]?.w);return sameWeight?{cls:'progression-good',text:'🟢 Gewicht erhöhen'}:{cls:'progression-warn',text:'🟡 Noch 1× bestätigen'}}
function localDateTimeInputValue(value){const d=new Date(value);if(Number.isNaN(d.getTime()))return '';const pad=n=>String(n).padStart(2,'0');return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())+'T'+pad(d.getHours())+':'+pad(d.getMinutes())}
function previousHtml(exercise){const prev=previousExercise(exercise.name);if(!prev)return `<div class="previous-compact"><span class="previous-line">Zuletzt: <b>noch kein Wert</b></span><span class="progression-mini progression-hold">Startwert</span></div>`;const status=progressionState(exercise),sets=prev.sets.slice(0,setCount(exercise.scheme)).map(x=>`${Number(x.w)>0?x.w+' kg':'Körpergewicht'} × ${x.r}`).join(' · ');return `<div class="previous-compact"><span class="previous-line"><span>Zuletzt</span><b>${sets}</b></span><span class="progression-mini ${status.cls}">${status.text.replace('🔴 ','').replace('🟢 ','').replace('🟡 ','')}</span></div>`}
function day(k){ensure(k);if(s.current.day!==k){view='day-'+s.current.day;k=s.current.day}let p=getPlan(k),c=s.current,exercises=c.exercises;const total=exercises.reduce((n,x,i)=>n+(c.skipped[i]||x.optional?0:setCount(x.scheme)),0),done=Object.entries(c.done).filter(([q,v])=>{const i=Number(q.split('-')[0]);return v&&!c.skipped[i]&&!exercises[i]?.optional&&Number(c.reps[q])>0&&(exercises[i]?.bodyweight||Number(c.values[q])>0)}).length,e=estimate(c);app.innerHTML=`<div class="top"><button class="btn secondary" id="back">← Zurück</button><button class="btn primary" id="finish" data-finish-mission>${c.editingIndex!==undefined?'Änderungen speichern':'Mission abschließen'}</button></div><h1>Mission ${k}</h1><div class="sub">${p.title}</div>
${c.editingIndex!==undefined?'<div class="edit-banner"><b>Bearbeitungsmodus</b><br>Du änderst eine bereits abgeschlossene Mission.</div>':''}
<div class="card date-row"><label>Datum und Uhrzeit</label><input class="field" id="missionDate" type="datetime-local" value="${localDateTimeInputValue(c.date)}"></div>
<div class="card"><div class="top"><h3 style="margin:0">Cardio</h3><button id="cardioDone" class="btn ${c.cardio.done?'primary':'secondary'}">${c.cardio.done?'✓ Erledigt':'Abhaken'}</button></div><div class="grid2"><div><label>Gerät</label><select id="ctype">${['Laufband','Laufband mit Steigung','Stepper','Fahrrad','Crosstrainer','Ruderergometer','Sonstiges'].map(x=>`<option ${c.cardio.type===x?'selected':''}>${x}</option>`).join('')}</select></div><div><label>Dauer (Min.)</label><input class="field" inputmode="decimal" id="cmin" value="${c.cardio.minutes}"></div><div><label>Intensität</label><select id="cint">${['locker','mittel','intensiv'].map(x=>`<option ${c.cardio.intensity===x?'selected':''}>${x}</option>`).join('')}</select></div><div><label>Geräte-kcal (optional)</label><input class="field" inputmode="numeric" id="cdevice" value="${c.cardio.device||''}"></div></div></div>
<div class="card progress-card"><div class="top"><b>${done}/${total} Pflichtsätze</b><span class="small">${total?Math.round(done/total*100):0}% · Cardio ${c.cardio.done?'✓':'offen'}</span></div><div class="progress"><div style="width:${total?Math.min(100,done/total*100):0}%"></div></div></div>
${exercises.map((x,i)=>{const skipped=!!c.skipped[i];return `<div class="card exercise-card ${x.optional?'optional':''} ${skipped?'exercise-skipped':''}"><div class="exercise-head"><div><div class="exercise-title">${i+1}. ${x.name}</div><div class="exercise-sub">${x.scheme} · ${x.muscles}${x.replacedFrom?` · ersetzt ${x.replacedFrom}`:''}</div></div>${x.optional?'<span class="badge" style="margin-top:0">optional</span>':''}</div>${skipped?'<div class="skip-banner">⏭️ Übersprungen</div>':previousHtml(x)}<div class="exercise-actions"><select data-replace-select="${i}" ${skipped?'disabled':''}><option value="">Alternative wählen …</option>${exerciseOptions()}</select><button class="btn secondary" data-confirm-replace="${i}" ${skipped?'disabled':''}>Ersetzen</button><button class="btn secondary" data-skip-exercise="${i}">${skipped?'Aktivieren':'Überspringen'}</button></div><div class="sets">${Array.from({length:setCount(x.scheme)},(_,j)=>{let q=i+'-'+j;return `<div class="set"><small>Satz ${j+1}</small><input inputmode="decimal" data-w="${q}" placeholder="kg" value="${c.values[q]||''}"><input inputmode="numeric" data-r="${q}" placeholder="Wdh." value="${c.reps[q]||''}"><button data-d="${q}" class="${c.done[q]&&Number(c.reps[q])>0?'done':''}">${c.done[q]&&Number(c.reps[q])>0?'✓':'Abhaken'}</button></div>`}).join('')}</div><details class="exercise-details"><summary>ⓘ Technikhinweis</summary><div class="exercise-details-content">${x.tip}</div></details><details class="exercise-note" ${c.exerciseNotes[i]?'open':''}><summary>Notiz${c.exerciseNotes[i]?' · vorhanden':''}</summary><input class="field" data-note="${i}" placeholder="z. B. Sitz höher einstellen" value="${c.exerciseNotes[i]||''}"></details></div>`}).join('')}
<div class="card"><h3 style="margin-top:0">Weitere Übung</h3><div class="grid2"><select id="extraExercise"><option value="">Übung auswählen …</option>${exerciseOptions()}</select><button class="btn primary" id="addExercise">Hinzufügen</button></div></div>
<div class="card"><h3 style="margin-top:0">Trainingsdaten</h3><div class="grid2"><div><label>Krafttraining (Min.)</label><input class="field" inputmode="numeric" id="smin" value="${c.strengthMinutes}"></div><div><label>Belastung</label><select id="effort">${['locker','mittel','hoch'].map(x=>`<option ${c.effort===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="small" style="margin-top:9px">Geschätzter Verbrauch: ca. <b>${e.total} kcal</b></div></div><div class="card"><label>Trainingsnotiz</label><textarea id="notes">${c.notes}</textarea></div><div class="card bottom-finish-card"><button class="btn primary" data-finish-mission style="width:100%">${c.editingIndex!==undefined?'Änderungen speichern':'🥷 Mission abschließen'}</button></div>`}
function estimate(c){let w=+s.profile.currentWeight||70,M={Laufband:[3.5,5,7],'Laufband mit Steigung':[4.5,6.5,8.5],Stepper:[5,7,9],Fahrrad:[4,6,8],Crosstrainer:[4.5,6.5,8],Ruderergometer:[4,6,8],Sonstiges:[3.5,5.5,7.5]},ix={locker:0,mittel:1,intensiv:2}[c.cardio?.intensity]??1,device=Number(c.cardio?.device),hasDevice=Number.isFinite(device)&&device>0,cardio=hasDevice?Math.round(device):Math.round((M[c.cardio?.type]||M.Sonstiges)[ix]*3.5*w/200*(+c.cardio?.minutes||0));let sm={locker:3,mittel:4.5,hoch:6}[c.effort]||4.5,strength=Math.round(sm*3.5*w/200*(+c.strengthMinutes||0));return{cardio,strength,total:cardio+strength,cardioSource:hasDevice?'Gerätewert':'Schätzung'}}
function personalRecords(){const best={};for(const h of s.history){const names=exerciseNamesForRecord(h);names.forEach((name,i)=>{if(h.skipped?.[i])return;for(let j=0;j<6;j++){const q=i+'-'+j;if(!validRecordSet(h,i,j))continue;const rs=recordSet(h,i,j),w=Number(rs.value),r=Number(rs.reps),clean=name.replace(' · optional','');if(!Number.isFinite(w)||w<=0)continue;if(!best[clean]||w>best[clean].weight||(w===best[clean].weight&&r>best[clean].reps))best[clean]={weight:w,reps:r,date:h.date}}})}return best}
function missionStats(h){
 if(h.manualCompleted)return{sets:0,completedExercises:0,activeExercises:(h.exerciseNames||[]).filter(n=>!String(n).includes('optional')).length,completion:100,requiredSets:0,completedRequiredSets:0};
 const names=exerciseNamesForRecord(h);let sets=0,completedExercises=0,activeExercises=0,requiredSets=0,completedRequiredSets=0;
 names.forEach((n,i)=>{
  if(h.skipped?.[i])return;
  const exercise=h.exerciseSnapshot?.[i]||h.exercises?.[i]||EXERCISE_LIBRARY.find(x=>x.name===n)||{scheme:'3×10–12'};
  const optional=!!exercise.optional||String(n).includes('optional')||(n==='Rückenstrecker'&&h.day==='A');
  const expected=setCount(exercise.scheme);
  let completedForExercise=0;
  for(let j=0;j<expected;j++){const q=i+'-'+j;if(validRecordSet(h,i,j)){sets++;completedForExercise++;if(!optional)completedRequiredSets++}}
  if(!optional){activeExercises++;requiredSets+=expected;if(completedForExercise===expected)completedExercises++}
 });
 const completion=requiredSets?Math.min(100,Math.round(completedRequiredSets/requiredSets*100)):100;
 return{sets,completedExercises,activeExercises,completion,requiredSets,completedRequiredSets};
}
function missionGrade(h){if(h.manualCompleted)return '✓';const st=missionStats(h),score=st.completion+(st.sets>=18?8:st.sets>=10?4:0)+(h.cardio?.done?5:0);return score>=108?'SS':score>=98?'S':score>=88?'A':score>=74?'B':score>=55?'C':'D'}
function workoutDuration(h){const end=new Date(h.completedAt||h.date),start=new Date(h.startedAt||h.date);const min=Math.round((end-start)/60000);return Number.isFinite(min)&&min>0&&min<360?min:(Number(h.strengthMinutes)||0)+(h.cardio?.done?Number(h.cardio.minutes)||0:0)}
function localMondayKey(date){const d=new Date(date);d.setHours(12,0,0,0);d.setDate(d.getDate()-((d.getDay()+6)%7));return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function weeklyMissionStats(){const weeks=new Map;for(const h of s.history){if(!h||!h.date)continue;const key=localMondayKey(h.date);weeks.set(key,(weeks.get(key)||0)+1)}const target=3,currentKey=localMondayKey(new Date()),currentCount=weeks.get(currentKey)||0;let streak=0,d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()-((d.getDay()+6)%7));if(currentCount>0){streak=1;d.setDate(d.getDate()-7)}else d.setDate(d.getDate()-7);while((weeks.get(localMondayKey(d))||0)>=target){streak++;d.setDate(d.getDate()-7)}return{streak,current:currentCount,target,completedCurrent:currentCount>=target}}
function streakWeeks(){return weeklyMissionStats().streak}
function periodSummary(months=1){const now=new Date(),from=new Date(now);from.setMonth(now.getMonth()-months+1,1);let trainings=0,sets=0,cardioMin=0,kcal=0,prs=0;const allPR=personalRecords();for(const h of s.history){if(new Date(h.date)<from)continue;trainings++;sets+=missionStats(h).sets;cardioMin+=h.cardio?.done?Number(h.cardio.minutes)||0:0;kcal+=estimate(h).total}prs=Object.values(allPR).filter(x=>new Date(x.date)>=from).length;return{trainings,sets,cardioMin,kcal,prs}}
function muscleSummary(){const out={Brust:0,Rücken:0,Schultern:0,Beine:0,Po:0,Bauch:0,Trapez:0};for(const h of s.history.slice(0,12)){const names=exerciseNamesForRecord(h);names.forEach((n,i)=>{if(h.skipped?.[i])return;let done=false;for(let j=0;j<6;j++)if(validRecordSet(h,i,j))done=true;if(!done)return;const exr=EXERCISE_LIBRARY.find(x=>x.name===n);const m=exr?.muscles||'';Object.keys(out).forEach(k=>{if(m.toLowerCase().includes(k.toLowerCase())||(k==='Schultern'&&m.includes('Schulter'))||(k==='Beine'&&(m.includes('Bein')||m.includes('Oberschenkel'))))out[k]++})})}return out}
function dashboard(){const latest=s.measurements.at(-1),first=s.measurements[0],metrics=['Gewicht','Bauchnabel','Hüfte','Brustwarze','Schenkel','Arm','Arm angespannt'];let selected=s.dashboardMetrics||['Gewicht'];if(selected.includes('Gewicht')&&selected.length>1)selected=['Gewicht'];if(!selected.length)selected=['Gewicht'];s.dashboardMetrics=selected;const delta=k=>{const v=(latest[k]??0)-(first[k]??0);return(v>0?'+':'')+v.toFixed(1)+(k==='Gewicht'?' kg':' cm')};const calorieItems=[];if(s.current){const e=estimate(s.current);calorieItems.push({id:'current',label:'Heute · laufende Mission',total:e.total,cardio:e.cardio,strength:e.strength})}s.history.forEach((h,i)=>{const c=estimate(h);calorieItems.push({id:'h'+i,label:new Date(h.date).toLocaleDateString('de-DE')+' · Mission '+h.day,total:c.total,cardio:c.cardio,strength:c.strength})});const selectedCalories=s.dashboardCalorieDay||calorieItems[0]?.id||'';const kcal=calorieItems.find(x=>x.id===selectedCalories)||calorieItems[0]||{total:0,cardio:0,strength:0};const mus=muscleSummary(),maxMus=Math.max(1,...Object.values(mus));app.innerHTML=`${brand()}<h2 class="scroll-title">Dashboard</h2><div class="metric-grid">${metrics.map(k=>`<div class="metric-card"><div class="small">${k}</div><strong>${latest[k]??'-'}${k==='Gewicht'?' kg':' cm'}</strong><div class="small">${delta(k)} seit Start</div></div>`).join('')}</div><div class="card"><b>Messwerte im Diagramm</b><div class="filter-row">${metrics.map(k=>`<button class="filter-chip ${selected.includes(k)?'active':''}" data-metric="${k}">${k}</button>`).join('')}</div><div id="chartLegend" class="legend"></div><div class="chart-axis-top" id="chartModeTitle">Darstellung</div><div class="chart-wrap"><canvas id="dynamicChart" class="chart"></canvas></div><div class="chart-note" id="chartExplanation"></div></div><div class="card"><h3 style="margin-top:0">Trainingsverteilung</h3><div class="dashboard-muscles">${Object.entries(mus).map(([name,v])=>`<div class="dashboard-muscle-row"><span>${name}</span><div class="progress"><div style="width:${v/maxMus*100}%"></div></div><b>${v}</b></div>`).join('')}</div></div><div class="card"><h3 style="margin-top:0">Kalorien nach Trainingstag</h3><label>Tag auswählen</label><select id="calorieDay">${calorieItems.length?calorieItems.map(x=>`<option value="${x.id}" ${x.id===selectedCalories?'selected':''}>${x.label}</option>`).join(''):'<option>Noch kein Training gespeichert</option>'}</select><div class="kcal-grid"><div class="kcal-card"><div class="small">Gesamt</div><strong>ca. ${kcal.total} kcal</strong></div><div class="kcal-card"><div class="small">Cardio</div><strong>${kcal.cardio} kcal</strong></div><div class="kcal-card"><div class="small">Krafttraining</div><strong>${kcal.strength} kcal</strong></div></div></div>${(()=>{const mo=periodSummary(1),yr=periodSummary(12);return `<div class="card"><h3 style="margin-top:0">Monats- und Jahresrückblick</h3><div class="summary-grid"><div class="summary-card"><strong>${mo.trainings}</strong>Trainings im Monat</div><div class="summary-card"><strong>${mo.cardioMin}</strong>Cardio-Minuten</div><div class="summary-card"><strong>${yr.trainings}</strong>Trainings in 12 Monaten</div><div class="summary-card"><strong>${yr.sets}</strong>Sätze in 12 Monaten</div></div></div>`})()}<div class="card"><h3>Neue Messung</h3><div class="grid2">${['date',...metrics].map(x=>`<div class="${x==='date'?'measurement-new-date':''}"><label>${x==='date'?'Datum':x}</label><input class="field mi" data-m="${x}" type="${x==='date'?'date':'number'}" step="0.1" ${x==='date'?`value="${new Date().toISOString().slice(0,10)}"`:''}></div>`).join('')}</div><button class="btn primary" id="addm" style="margin-top:12px">Speichern</button></div><div class="card"><div class="measurement-section-title"><div><h3 style="margin:0">Bisherige Messungen</h3><div class="small">Neueste Messung zuerst</div></div><span class="measurement-count">${s.measurements.length} Einträge</span></div><div class="measurement-history">${[...s.measurements].reverse().map((x,ri)=>{const originalIndex=s.measurements.length-1-ri,prev=originalIndex>0?s.measurements[originalIndex-1]:null;const wd=prev&&Number.isFinite(Number(x.Gewicht))&&Number.isFinite(Number(prev.Gewicht))?Number(x.Gewicht)-Number(prev.Gewicht):null;const value=(label,key)=>{const v=x[key];return `<div class="measurement-value"><span>${label}</span><b class="${v==null?'measurement-empty':''}">${v==null?'–':v+' cm'}</b></div>`};return `<div class="measurement-entry"><div class="measurement-head"><div><div class="measurement-date">${new Date(x.date+'T12:00:00').toLocaleDateString('de-DE',{weekday:'short',day:'2-digit',month:'2-digit',year:'numeric'})}</div>${ri===0?'<span class="pill" style="margin-top:7px">Aktuell</span>':''}</div><div class="measurement-weight"><strong>${x.Gewicht??'–'} kg</strong><span>${wd==null?'Gewicht':`${wd>0?'+':''}${wd.toFixed(1)} kg zur vorherigen Messung`}</span></div></div><div class="measurement-values">${value('Bauchnabel','Bauchnabel')}${value('Hüfte','Hüfte')}${value('Brust','Brustwarze')}${value('Schenkel','Schenkel')}${value('Arm','Arm')}${value('Arm angespannt','Arm angespannt')}</div></div>`}).join('')}</div></div>`;setTimeout(()=>drawDynamicChart(selected),0)}
function drawDynamicChart(selected){const colors=['#ff9b2f','#ff5d3d','#ffd057','#65d08b','#a58cff','#67cfff','#ff84c8'];const isWeight=selected.length===1&&selected[0]==='Gewicht';const series=selected.map((k,i)=>({name:k,values:s.measurements.map(x=>Number(x[k])||0),color:colors[i%colors.length],unit:isWeight?'kg':'cm'}));const legend=document.getElementById('chartLegend');if(legend)legend.innerHTML=series.map(q=>`<div class="legend-item"><span class="legend-dot" style="background:${q.color};box-shadow:0 0 8px ${q.color}88"></span><span>${q.name}: <b>${q.values.at(-1).toFixed(1)} ${q.unit}</b></span></div>`).join('');const title=document.getElementById('chartModeTitle');if(title)title.textContent=isWeight?'Gewichtsverlauf (kg)':'Umfangsverlauf (cm)';const explanation=document.getElementById('chartExplanation');if(explanation)explanation.textContent=isWeight?'Die horizontale Achse zeigt das Datum, die vertikale Achse dein Gewicht in Kilogramm.':'Die horizontale Achse zeigt das Datum, die vertikale Achse die ausgewählten Körperumfänge in Zentimetern.';const canvas=document.getElementById('dynamicChart');if(!canvas||!series.length)return;const width=Math.max(320,canvas.clientWidth),height=300,dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=width*dpr;canvas.height=height*dpr;const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,width,height);const left=48,right=14,top=24,bottom=46;let values=series.flatMap(q=>q.values),min=Math.min(...values),max=Math.max(...values);if(min===max){min-=1;max+=1}const rawRange=max-min,stepBase=rawRange/4,magnitude=Math.pow(10,Math.floor(Math.log10(stepBase||1))),niceStep=Math.max(magnitude,Math.ceil(stepBase/magnitude)*magnitude);min=Math.floor((min-niceStep*.35)/niceStep)*niceStep;max=Math.ceil((max+niceStep*.35)/niceStep)*niceStep;const range=max-min||1;ctx.font='600 12px -apple-system,sans-serif';ctx.textAlign='right';ctx.textBaseline='middle';for(let i=0;i<=4;i++){const ratio=i/4,y=top+(height-top-bottom)*ratio,value=max-range*ratio;ctx.strokeStyle='rgba(255,209,159,.13)';ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(width-right,y);ctx.stroke();ctx.fillStyle='#efd6c7';ctx.fillText(value.toFixed(value<10?1:0),left-8,y)}ctx.textAlign='center';ctx.textBaseline='top';ctx.font='600 11px -apple-system,sans-serif';s.measurements.forEach((m,i)=>{const x=left+i*((width-left-right)/(s.measurements.length-1||1));ctx.fillStyle='#d8bfb1';ctx.fillText(new Date(m.date).toLocaleDateString('de-DE',{day:'2-digit',month:'2-digit'}),x,height-bottom+13)});ctx.fillStyle='#ffcc91';ctx.font='700 11px -apple-system,sans-serif';ctx.textAlign='left';ctx.fillText(isWeight?'Gewicht (kg)':'Umfang (cm)',left,9);series.forEach(q=>{const pts=q.values.map((v,i)=>({x:left+i*((width-left-right)/(q.values.length-1||1)),y:top+(max-v)/range*(height-top-bottom)}));ctx.save();ctx.strokeStyle=q.color;ctx.lineWidth=3;ctx.lineJoin='round';ctx.lineCap='round';ctx.shadowColor=q.color;ctx.shadowBlur=9;ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke();ctx.restore();pts.forEach((p,i)=>{ctx.fillStyle='#120a07';ctx.strokeStyle=q.color;ctx.lineWidth=3;ctx.beginPath();ctx.arc(p.x,p.y,5,0,Math.PI*2);ctx.fill();ctx.stroke();if(i===0||i===pts.length-1){ctx.fillStyle='#fff6ec';ctx.font='700 10px -apple-system,sans-serif';ctx.textAlign='center';ctx.fillText(`${q.values[i].toFixed(1)} ${q.unit}`,p.x,Math.max(top,p.y-18))}})})}
function chart(id,series){let c=document.getElementById(id),ctx=c.getContext('2d'),w=c.width=c.clientWidth*2,h=c.height=420,vals=series.flatMap(x=>x.v),mn=Math.min(...vals),mx=Math.max(...vals),pad=45,col=['#ff8a1f','#ff5a36'];ctx.scale(2,2);ctx.strokeStyle='#4b2a1d';for(let i=0;i<4;i++){let y=25+i*50;ctx.beginPath();ctx.moveTo(20,y);ctx.lineTo(w/2-20,y);ctx.stroke()}series.forEach((q,z)=>{ctx.strokeStyle=col[z];ctx.lineWidth=3;ctx.beginPath();q.v.forEach((v,i)=>{let x=25+i*((w/2-50)/(q.v.length-1||1)),y=180-(v-mn)/(mx-mn||1)*140;i?ctx.lineTo(x,y):ctx.moveTo(x,y);ctx.fillStyle=col[z];ctx.fillRect(x-3,y-3,6,6)});ctx.stroke();ctx.fillStyle=col[z];ctx.fillText(q.n,25+z*85,15)})}
function charts(){chart('cw',[{n:'Gewicht',v:s.measurements.map(x=>x.Gewicht)}]);chart('cm',[{n:'Bauch',v:s.measurements.map(x=>x.Bauchnabel)},{n:'Hüfte',v:s.measurements.map(x=>x.Hüfte)}])}
function history(){const latest=s.history[0],latestStats=latest?missionStats(latest):null,latestResult=latest?{grade:missionGrade(latest),sets:latestStats.sets,completion:latestStats.completion,duration:workoutDuration(latest),newPRs:s.lastMissionResult?.newPRs||0}:null;app.innerHTML=`${brand()}<h2>Missionsverlauf</h2>${latestResult?`<div class="card rank-result pr-flash"><div class="small">Letzte Missionsbewertung</div><div class="rank-letter">${latestResult.grade}</div><b>${latestResult.sets} Sätze · ${latestResult.completion}% abgeschlossen</b><div class="meta">${latestResult.duration} Min. · ${latestResult.newPRs} neue Rekorde</div></div>`:''}${s.history.length?s.history.map((x,i)=>{const st=missionStats(x);return `<div class="card history-card"><div class="top"><div><b>Mission ${x.day} · ${x.title}</b><div class="meta">${new Date(x.date).toLocaleString('de-DE')} · ${workoutDuration(x)} Min.</div></div><span class="mission-rank">${missionGrade(x)}-Rang</span></div><div class="meta" style="margin-top:8px">${x.cardio?.done?(x.cardio?.type||'Cardio')+' '+(x.cardio?.minutes||0)+' Min.':'Cardio nicht absolviert'} · ca. ${estimate(x).total} kcal<br>${st.sets} absolvierte Sätze · ${st.completion}% der Mission</div><div class="history-actions"><button class="btn primary" data-view-history="${i}">Zusammenfassung ansehen</button><button class="btn-edit" data-edit-history="${i}">Bearbeiten</button><button class="btn-delete" data-delete-history="${i}">Löschen</button></div></div>`}).join(''):'<div class="card">Noch keine Mission abgeschlossen.</div>'}`}
function missionSummary(i){const x=s.history[i];if(!x){view='history';render();return}const names=exerciseNamesForRecord(x),st=missionStats(x),grade=missionGrade(x),duration=workoutDuration(x);app.innerHTML=`<button class="btn secondary back-from-summary" id="summaryBack">← Zum Verlauf</button><div id="summaryCapture"><div class="readonly-hero"><div class="small">ABGESCHLOSSENE MISSION</div><div class="share-card-title">Mission ${x.day}</div><div>${x.title}</div><div class="rank-letter">${grade}</div><b>${new Date(x.date).toLocaleDateString('de-DE')} · ${duration} Minuten</b></div><div class="summary-grid" style="margin-top:12px"><div class="summary-card"><strong>${st.sets}</strong>Sätze</div><div class="summary-card"><strong>${st.completion}%</strong>abgeschlossen</div><div class="summary-card"><strong>${x.cardio?.done?Number(x.cardio.minutes)||0:0}</strong>Cardio-Minuten</div><div class="summary-card"><strong>${estimate(x).total}</strong>ca. kcal</div></div><div class="card"><h3 style="margin-top:0">Cardio</h3>${x.cardio?.done?`<b>${x.cardio.type||'Cardio'} · ${x.cardio.minutes||0} Min.</b><div class="meta">Intensität: ${x.cardio.intensity||'–'}${x.cardio.device?` · Gerät: ${x.cardio.device} kcal`:''}</div>`:'<div class="meta">Nicht absolviert</div>'}</div><div class="card"><h3 style="margin-top:0">Krafttraining</h3>${names.map((name,ei)=>{if(x.skipped?.[ei])return `<div class="readonly-exercise"><b>${ei+1}. ${name}</b><div class="small">⏭️ Übersprungen</div></div>`;const sets=[];for(let j=0;j<6;j++){const q=ei+'-'+j;if(validRecordSet(x,ei,j)){const rs=recordSet(x,ei,j);sets.push(`<span class="readonly-set">Satz ${j+1}: ${rs.value} kg × ${rs.reps}</span>`)}}return `<div class="readonly-exercise"><b>${ei+1}. ${name}</b><div class="readonly-sets">${sets.length?sets.join(''):'<span class="small">Nicht absolviert</span>'}</div>${x.exerciseNotes?.[ei]?`<div class="small" style="margin-top:7px">Notiz: ${x.exerciseNotes[ei]}</div>`:''}</div>`}).join('')}</div>${x.notes?`<div class="card"><b>Trainingsnotiz</b><div class="meta">${x.notes}</div></div>`:''}<div class="share-card-footer">SHINOBI FIT · ${grade}-RANG</div></div><div class="readonly-actions"><button class="btn primary" data-edit-history="${i}">✏️ Mission bearbeiten</button><button class="btn secondary" id="cardMode">📷 Trainingskarte anzeigen</button></div>`}
function more(){const bm=JSON.parse(localStorage.getItem(BACKUP_META_KEY)||'null');const backupText=bm?.createdAt?new Date(bm.createdAt).toLocaleString('de-DE')+' · '+(bm.reason||'Sicherung'):'Noch keine lokale Sicherung';const records=Object.entries(personalRecords()).sort((a,b)=>b[1].weight-a[1].weight);app.innerHTML=`${brand()}<h2>Mehr</h2><div class="card"><div class="more-section-title"><h3 style="margin:0">Shinobi-Rangliste</h3><span class="pill">20 Ränge</span></div><div class="rank-path-large">${rankPathHtml()}</div></div><div class="card"><h3 style="margin-top:0">Erfolge</h3>${achievementsHtml()}</div><div class="card"><h3 style="margin-top:0">Persönliche Rekorde</h3><div class="record-grid">${records.map(([name,v])=>`<div class="metric-card"><div class="small">${name}</div><strong>${v.weight} kg</strong><div class="small">${v.reps} Wdh. · ${new Date(v.date).toLocaleDateString('de-DE')}</div></div>`).join('')||'<div class="small">Noch keine Kraftwerte gespeichert.</div>'}</div></div><div class="card"><b>Datensicherung</b><div class="meta" style="margin:6px 0 12px">Letzte lokale Sicherung: ${backupText}</div><div class="backup-actions"><button class="btn primary" id="createBackup">Backup erstellen</button><button class="btn secondary" id="restoreBackup">Wiederherstellen</button><button class="btn secondary" id="export">Datei exportieren</button><button class="btn secondary" id="importBtn">Datei importieren</button><input id="importFile" type="file" accept="application/json,.json" hidden></div></div><div class="card"><b>Über Shinobi Fit</b><div class="meta">Installierte Version ${APP_VERSION}</div></div><div class="card data-danger"><b>Datenverwaltung</b><div class="meta" style="margin:6px 0 12px">Löscht alle lokal gespeicherten Trainings-, Mess- und App-Daten auf diesem Gerät.</div><button class="btn secondary" id="reset">Alle Daten löschen</button></div>`}
function flushCurrentInputs(){
 if(!s.current)return;
 document.querySelectorAll('[data-w]').forEach(x=>{s.current.values[x.dataset.w]=x.value});
 document.querySelectorAll('[data-r]').forEach(x=>{s.current.reps[x.dataset.r]=x.value});
 document.querySelectorAll('[data-note]').forEach(x=>{s.current.exerciseNotes[x.dataset.note]=x.value});
 const map=[['ctype','type'],['cmin','minutes'],['cint','intensity'],['cdevice','device']];
 map.forEach(([id,key])=>{const el=document.getElementById(id);if(el)s.current.cardio[key]=el.value});
 const sm=document.getElementById('smin'),ef=document.getElementById('effort'),nt=document.getElementById('notes');
 if(sm)s.current.strengthMinutes=sm.value;if(ef)s.current.effort=ef.value;if(nt)s.current.notes=nt.value;
}
function bind(){
document.querySelectorAll('[data-view-history]').forEach(btn=>btn.onclick=()=>{view='summary-'+btn.dataset.viewHistory;render()});
if(document.getElementById('summaryBack'))document.getElementById('summaryBack').onclick=()=>{document.body.classList.remove('training-card-mode');view='history';render()};
if(document.getElementById('cardMode'))document.getElementById('cardMode').onclick=()=>{document.body.classList.toggle('training-card-mode');const cap=document.getElementById('summaryCapture');if(cap)cap.classList.toggle('share-card');document.getElementById('cardMode').textContent=document.body.classList.contains('training-card-mode')?'Normale Ansicht':'📷 Trainingskarte anzeigen';window.scrollTo({top:0,behavior:'smooth'})};
document.querySelectorAll('[data-edit-history]').forEach(btn=>btn.onclick=()=>{document.body.classList.remove('training-card-mode');
  const i=Number(btn.dataset.editHistory);
  const original=s.history[i];
  if(!original)return;
  s.current=JSON.parse(JSON.stringify(original));
  s.current.editingIndex=i;
  save();
  view='day-'+s.current.day;
  render();
});
document.querySelectorAll('[data-delete-history]').forEach(btn=>btn.onclick=()=>{
  const i=Number(btn.dataset.deleteHistory);
  const item=s.history[i];
  if(!item)return;
  if(confirm(`Mission ${item.day} vom ${new Date(item.date).toLocaleDateString('de-DE')} wirklich löschen?`)){
    s.history.splice(i,1);
    recalcChakra();
    save();
    render();
  }
});
const calorieDay=document.getElementById('calorieDay');
if(calorieDay)calorieDay.onchange=()=>{s.dashboardCalorieDay=calorieDay.value;save();render()};
document.querySelectorAll('[data-metric]').forEach(b=>b.onclick=()=>{s.dashboardMetrics=s.dashboardMetrics||['Gewicht'];const k=b.dataset.metric;if(k==='Gewicht')s.dashboardMetrics=['Gewicht'];else{if(s.dashboardMetrics.includes('Gewicht'))s.dashboardMetrics=[k];else if(s.dashboardMetrics.includes(k)){if(s.dashboardMetrics.length>1)s.dashboardMetrics=s.dashboardMetrics.filter(x=>x!==k)}else s.dashboardMetrics.push(k)}save();render()});document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>{view=b.dataset.v;render()});document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{const target=b.dataset.day;if(s.current&&s.current.day!==target){const choice=confirm(`Mission ${s.current.day} läuft bereits. OK = fortsetzen, Abbrechen = laufende Mission verwerfen und Mission ${target} starten.`);if(choice){view='day-'+s.current.day;render();return}else{s.current=null;save()}}view='day-'+target;render()});let q=id=>document.getElementById(id);
if(q('missionDate'))q('missionDate').onchange=()=>{
  const value=q('missionDate').value;
  if(value){s.current.date=new Date(value).toISOString();save();}
};
if(q('back'))q('back').onclick=()=>{view='workouts';render()};
document.querySelectorAll('[data-w]').forEach(x=>x.oninput=()=>{s.current.values[x.dataset.w]=x.value;save()});
document.querySelectorAll('[data-r]').forEach(x=>x.oninput=()=>{s.current.reps[x.dataset.r]=x.value;save()});
document.querySelectorAll('[data-note]').forEach(x=>x.oninput=()=>{s.current.exerciseNotes[x.dataset.note]=x.value;save()});
document.querySelectorAll('[data-d]').forEach(x=>x.onclick=()=>{flushCurrentInputs();const key=x.dataset.d;if(!s.current.done[key]){const [exerciseIndex]=key.split('-').map(Number),exercise=s.current.exercises[exerciseIndex];if(Number(s.current.reps[key])<=0)return alert('Bitte zuerst gültige Wiederholungen eintragen.');if(!exercise?.bodyweight&&Number(s.current.values[key])<=0)return alert('Bitte zuerst ein gültiges Gewicht eintragen.');}s.current.done[key]=!s.current.done[key];const [ei,si]=key.split('-').map(Number);let nextKey=null;if(s.current.done[key]){for(let i=ei;i<s.current.exercises.length&&!nextKey;i++){const start=i===ei?si+1:0;for(let j=start;j<setCount(s.current.exercises[i].scheme);j++){const candidate=i+'-'+j;if(!s.current.done[candidate]){nextKey=candidate;break}}}}save();render();if(nextKey)setTimeout(()=>{const field=document.querySelector(`[data-r="${nextKey}"]`);if(field){field.focus();field.select()}},0)});
[['ctype','type'],['cmin','minutes'],['cint','intensity'],['cdevice','device']].forEach(([id,k])=>{if(q(id)){q(id).oninput=()=>{s.current.cardio[k]=q(id).value;save()};q(id).onchange=()=>{s.current.cardio[k]=q(id).value;save();if(id==='ctype'||id==='cint')render()}}});
if(q('cardioDone'))q('cardioDone').onclick=()=>{s.current.cardio.done=!s.current.cardio.done;save();render()};
if(q('smin'))q('smin').oninput=()=>{s.current.strengthMinutes=q('smin').value;save()};
if(q('effort'))q('effort').onchange=()=>{s.current.effort=q('effort').value;save();render()};
if(q('notes'))q('notes').oninput=()=>{s.current.notes=q('notes').value;save()};
document.querySelectorAll('[data-confirm-replace]').forEach(btn=>btn.onclick=()=>{const i=Number(btn.dataset.confirmReplace),sel=document.querySelector(`[data-replace-select="${i}"]`);if(!sel?.value)return alert('Bitte zuerst eine Alternative auswählen.');const old=s.current.exercises[i],replacement=JSON.parse(JSON.stringify(EXERCISE_LIBRARY.find(x=>x.name===sel.value)));replacement.replacedFrom=old.replacedFrom||old.name;s.current.exercises[i]=replacement;s.current.skipped[i]=false;for(let j=0;j<6;j++){delete s.current.values[i+'-'+j];delete s.current.reps[i+'-'+j];delete s.current.done[i+'-'+j]}const prev=previousExercise(replacement.name);if(prev)for(let j=0;j<setCount(replacement.scheme);j++){const set=prev.sets[j]||prev.sets.at(-1);if(set){s.current.values[i+'-'+j]=set.w;s.current.reps[i+'-'+j]=set.r}}save();render()});
document.querySelectorAll('[data-skip-exercise]').forEach(btn=>btn.onclick=()=>{const i=Number(btn.dataset.skipExercise);s.current.skipped[i]=!s.current.skipped[i];if(s.current.skipped[i]){for(let j=0;j<6;j++)s.current.done[i+'-'+j]=false;s.lastSkipped={index:i,name:s.current.exercises[i].name}}save();render();if(s.current.skipped[i]){const t=document.createElement('div');t.className='toast';t.innerHTML=`${s.current.exercises[i].name} übersprungen · <u>erneut tippen zum Aktivieren</u>`;document.body.appendChild(t);setTimeout(()=>t.remove(),2600)}});
if(q('addExercise'))q('addExercise').onclick=()=>{const name=q('extraExercise').value;if(!name)return alert('Bitte zuerst eine Übung auswählen.');const item=JSON.parse(JSON.stringify(EXERCISE_LIBRARY.find(x=>x.name===name)));const i=s.current.exercises.length;s.current.exercises.push(item);const prev=previousExercise(name);if(prev)for(let j=0;j<setCount(item.scheme);j++){const set=prev.sets[j]||prev.sets.at(-1);if(set){s.current.values[i+'-'+j]=set.w??'';s.current.reps[i+'-'+j]=set.r??''}}save();render()};

if(q('addCustomExercise'))q('addCustomExercise').onclick=()=>{const row=document.createElement('div');row.className='grid2 custom-ex-row';row.innerHTML=`<select class="custom-exercise"><option value="">Übung auswählen …</option>${exerciseOptions()}</select><label class="pill"><input type="checkbox" class="custom-optional"> optional</label>`;q('customExerciseRows').appendChild(row)};
if(q('saveCustomMission'))q('saveCustomMission').onclick=()=>{const title=q('customMissionName').value.trim();const rows=[...document.querySelectorAll('.custom-ex-row')];const exercises=rows.map(r=>{const name=r.querySelector('.custom-exercise').value;if(!name)return null;const item=JSON.parse(JSON.stringify(EXERCISE_LIBRARY.find(x=>x.name===name)));item.optional=r.querySelector('.custom-optional').checked;return item}).filter(Boolean);if(!title||!exercises.length)return alert('Bitte Namen und mindestens eine Übung auswählen.');s.customMissions.push({id:'custom-'+Date.now(),title,exercises});save();render()};
document.querySelectorAll('[data-delete-custom]').forEach(b=>b.onclick=()=>{if(confirm('Eigene Mission wirklich löschen?')){s.customMissions=s.customMissions.filter(m=>m.id!==b.dataset.deleteCustom);save();render()}});
const finishMission=()=>{flushCurrentInputs();save();const completedSets=Object.entries(s.current.done||{}).filter(([q,v])=>{const i=Number(q.split('-')[0]),exercise=s.current.exercises?.[i];return v&&!s.current.skipped?.[i]&&Number(s.current.reps[q])>0}).length;if(!s.current.cardio.done&&!completedSets)return alert('Die Mission ist noch leer. Bitte mindestens Cardio oder einen gültigen Satz absolvieren.');let e=estimate(s.current),p=getPlan(s.current.day),editingIndex=s.current.editingIndex,before=personalRecords(),rankBefore=characterRankIndex();const record={...s.current,title:p.title,kcal:e.total,exerciseNames:s.current.exercises.map(x=>x.name),exerciseSnapshot:s.current.exercises.map((x,i)=>({name:x.name,scheme:x.scheme,optional:!!x.optional,bodyweight:!!x.bodyweight,values:Object.fromEntries(Array.from({length:6},(_,j)=>[j,s.current.values[i+'-'+j]]).filter(([,v])=>v!==undefined)),reps:Object.fromEntries(Array.from({length:6},(_,j)=>[j,s.current.reps[i+'-'+j]]).filter(([,v])=>v!==undefined)),done:Object.fromEntries(Array.from({length:6},(_,j)=>[j,!!s.current.done[i+'-'+j]]))})),completedAt:new Date().toISOString()};delete record.editingIndex;if(editingIndex!==undefined&&s.history[editingIndex])s.history[editingIndex]=record;else s.history.unshift(record);s.history.sort((a,b)=>new Date(b.date)-new Date(a.date));recalcChakra();const after=personalRecords(),newPRs=Object.keys(after).filter(k=>!before[k]||after[k].weight>before[k].weight||(after[k].weight===before[k].weight&&after[k].reps>before[k].reps)).length,st=missionStats(record);s.lastMissionResult={grade:missionGrade(record),sets:st.sets,completion:st.completion,duration:workoutDuration(record),newPRs};const rankAfter=characterRankIndex();s.current=null;save();view='summary-'+s.history.indexOf(record);render();if(rankAfter>rankBefore)setTimeout(()=>showRankUp(CHARACTER_RANKS[rankAfter]),80)};document.querySelectorAll('[data-finish-mission]').forEach(btn=>btn.onclick=finishMission);if(q('addm'))q('addm').onclick=()=>{let m={};document.querySelectorAll('.mi').forEach(x=>{const k=x.dataset.m;m[k]=k==='date'?x.value:(x.value.trim()===''?null:Number(x.value))});if(!m.date||m.Gewicht===null||!Number.isFinite(m.Gewicht))return alert('Bitte Datum und Gewicht eintragen.');s.measurements.push(m);carryForwardMeasurements();s.profile.currentWeight=m.Gewicht;save();render()};if(q('savew'))q('savew').onclick=()=>{s.profile.currentWeight=+q('weight').value||s.profile.currentWeight;save();render()};if(q('createBackup'))q('createBackup').onclick=()=>{createLocalBackup('Manuell erstellt');alert('Lokales Backup wurde erstellt.');render()};if(q('restoreBackup'))q('restoreBackup').onclick=()=>{const raw=localStorage.getItem(BACKUP_KEY);if(!raw)return alert('Es ist noch kein lokales Backup vorhanden.');if(!confirm('Aktuelle Daten durch das letzte lokale Backup ersetzen?'))return;try{const payload=JSON.parse(raw);const data=payload.data||payload;if(!data||!Array.isArray(data.history)||!Array.isArray(data.measurements))throw new Error();s=data;migrateSeedHistory();recalcChakra();carryForwardMeasurements();localStorage.setItem(KEY,JSON.stringify(s));alert('Backup wurde wiederhergestellt.');view='home';render()}catch(e){alert('Das lokale Backup konnte nicht wiederhergestellt werden.')}};if(q('export'))q('export').onclick=()=>{let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({version:APP_VERSION,createdAt:new Date().toISOString(),data:s},null,2)],{type:'application/json'}));a.download='shinobi-fit-backup-v14.0.1.json';a.click()};if(q('importBtn'))q('importBtn').onclick=()=>q('importFile').click();if(q('importFile'))q('importFile').onchange=async()=>{const file=q('importFile').files?.[0];if(!file)return;try{const parsed=JSON.parse(await file.text());const data=parsed.data||parsed;if(!data||typeof data!=='object'||!Array.isArray(data.history)||!Array.isArray(data.measurements))throw new Error('Ungültiges Backup');s=data;s.history=s.history||[];s.measurements=s.measurements||INITIAL;s.profile=s.profile||{currentWeight:70,targetWeight:65};s.current=s.current||null;s.xp=s.xp||0;s.lastMissionResult=s.lastMissionResult||null;s.customMissions=s.customMissions||[];migrateSeedHistory();recalcChakra();save();alert('Backup erfolgreich importiert.');view='home';render()}catch(e){alert('Das Backup konnte nicht importiert werden.')}finally{q('importFile').value=''}};if(q('reset'))q('reset').onclick=()=>{if(confirm('Alle lokalen Daten löschen?')){localStorage.removeItem(KEY);location.reload()}}}
if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(reg=>reg.update()).catch(()=>{});}render();
